ALTER TABLE "products" ADD COLUMN "purchaseUnit" TEXT, ADD COLUMN "purchasePackSize" INTEGER NOT NULL DEFAULT 1 CHECK ("purchasePackSize" > 0), ADD COLUMN "leadTimeDays" INTEGER CHECK ("leadTimeDays" >= 0);
ALTER TABLE "purchase_order_items" ADD COLUMN "purchaseUnit" TEXT, ADD COLUMN "purchasePackSize" INTEGER NOT NULL DEFAULT 1;
CREATE TABLE "inventory_lots" ("id" UUID PRIMARY KEY, "inventoryId" UUID NOT NULL REFERENCES "inventories"("id"), "code" TEXT NOT NULL, "expiresAt" DATE, "quantity" INTEGER NOT NULL CHECK ("quantity" >= 0), "status" TEXT NOT NULL DEFAULT 'AVAILABLE', "purchaseOrderItemId" UUID REFERENCES "purchase_order_items"("id"), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX ON "inventory_lots" ("inventoryId", "status", "expiresAt");
CREATE TABLE "lot_movements" ("id" UUID PRIMARY KEY, "lotId" UUID NOT NULL REFERENCES "inventory_lots"("id"), "quantity" INTEGER NOT NULL, "referenceType" TEXT NOT NULL, "referenceId" TEXT NOT NULL, "actorId" UUID NOT NULL REFERENCES "users"("id"), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX ON "lot_movements" ("referenceType", "referenceId");
CREATE TABLE "lot_disposals" ("id" UUID PRIMARY KEY, "lotId" UUID NOT NULL REFERENCES "inventory_lots"("id"), "quantity" INTEGER NOT NULL CHECK ("quantity" > 0), "reason" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'PENDING', "createdById" UUID NOT NULL REFERENCES "users"("id"), "approvedById" UUID REFERENCES "users"("id"), "completedById" UUID REFERENCES "users"("id"), "evidence" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "completedAt" TIMESTAMP(3));
